.darma-loader-darma-b7-metronome-pendulum { --accent: var(--loader-color, #b45309); --accent-2: var(--loader-secondary-color, #ef4444); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b7-metronome-pendulum span { position: absolute; left: 50%; top: 12%; width: calc(var(--loader-size, 80px) * .05); height: 76%; margin-left: calc(var(--loader-size, 80px) * -.025); background: var(--accent); border-radius: calc(var(--loader-size, 80px) * .05); transform-origin: 50% 100%; animation: darma-loader-darma-b7-metronome-pendulum-swing calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b7-metronome-pendulum span::after { content: ''; position: absolute; top: -8%; left: 50%; width: calc(var(--loader-size, 80px) * .24); height: calc(var(--loader-size, 80px) * .24); margin-left: calc(var(--loader-size, 80px) * -.12); border-radius: 50%; background: var(--accent-2); }
@keyframes darma-loader-darma-b7-metronome-pendulum-swing { 0%, 100% { transform: rotate(38deg); } 50% { transform: rotate(-38deg); } }

